css:
.services-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 20px; }
.service-card {
  background: var(--bg-alt); border: 1px solid var(--border); border-radius: 16px; padding: 32px;
  display: flex; flex-direction: column; gap: 20px; min-height: 220px; transition: border-color 0.3s;
}
.service-card:hover { border-color: var(--accent); }
.service-card .top-row { display: flex; justify-content: space-between; align-items: flex-start; }
.service-icon {
  width: 48px; height: 48px; border-radius: 10px; background: rgba(14,165,233,0.1); color: var(--accent);
  display: flex; align-items: center; justify-content: center;
}
.service-num { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-dimmer); letter-spacing: 0.15em; }
.service-card .body { flex: 1; }
.service-card .title { font-family: 'Sora', sans-serif; font-weight: 700; font-size: 22px; letter-spacing: -0.02em; margin-bottom: 10px; }
.service-card .desc { font-family: 'Manrope', sans-serif; font-size: 14px; color: var(--text-muted); line-height: 1.55; }

@media (max-width: 560px) {
  .services-grid { grid-template-columns: 1fr; }
}
